import{_ as a,o as s,c as i,a3 as t}from"./chunks/framework.0y4FC009.js";const u=JSON.parse('{"title":"The release model","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/release-model.md","filePath":"explanation/release-model.md"}'),l={name:"explanation/release-model.md"};function r(o,e,n,d,h,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="the-release-model" tabindex="-1">The release model <a class="header-anchor" href="#the-release-model" aria-label="Permalink to &quot;The release model&quot;">​</a></h1><p>Releases are <strong>tag-only</strong> — there is no crates.io publish and no GitHub Releases artifact. <code>kuda</code>&#39;s crates are lib-only engines; the user-facing command is the tamias pack in <code>libraries/kuda</code>.</p><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><p><code>scripts/release.sh</code> is an operator-run shim over <a href="https://9aia.com/tarsi/" target="_blank" rel="noreferrer"><code>tarsi-serve</code></a> — the org release plane (project ADR-0005). One call runs plan → changelog → bump → tag → push; <code>tarsi-serve release</code> is dry-run by default and the script passes <code>--yes</code> as the explicit opt-in.</p><p>Repo policy lives in <code>tarsi.toml</code>:</p><ul><li><code>[publish.crates] enabled = false</code> — crates.io publishing is tamias-only (ADR-0004).</li><li><code>[publish.ghreleases] enabled = false</code> — org releases are tag-only; the capability stays for opt-in.</li><li><code>[release.sync_refs]</code> rewrites <code>libraries/kuda/tamias.yaml</code>&#39;s <code>version:</code> and the README&#39;s <code>kuda@&lt;ver&gt;</code> install ref inside the release commit, so the tagged tree is self-consistent.</li></ul><p>Units default to cargo workspace members; versions are workspace-inherited, so releasing units share one bump.</p><h2 id="shipping-the-command" tabindex="-1">Shipping the command <a class="header-anchor" href="#shipping-the-command" aria-label="Permalink to &quot;Shipping the command&quot;">​</a></h2><p>Tagging doesn&#39;t publish anything user-facing. The pack ships manually:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/pack.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                # stage driver payload</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   → release-builds tamias-driver-kuda into</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#     libraries/kuda/drivers/bin/&lt;triple&gt;/ (gitignored)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> publish</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libraries/kuda</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # → 9aia:kuda@&lt;ver&gt;</span></span></code></pre></div><p>Install is then <code>tamias install 9aia:kuda@&lt;ver&gt;</code> (needs <code>TAMIAS_REGISTRY_TOKEN</code>) or <code>tamias install --allow-drivers ./libraries/kuda</code> from a checkout.</p><h2 id="why-this-shape" tabindex="-1">Why this shape <a class="header-anchor" href="#why-this-shape" aria-label="Permalink to &quot;Why this shape&quot;">​</a></h2><ul><li><strong>Tag-only + pack publish</strong> matches the org distribution model: git/tag deps and the tamias registry are the channels; crates.io and GitHub Releases stay unused.</li><li><strong>tarsi over bespoke scripts</strong>: plan/changelog/bump/tag is the same pipeline every org repo runs — the repo keeps only policy (<code>tarsi.toml</code>), not machinery.</li><li><strong><code>dist-workspace.toml</code> is configured but idle</strong> — prebuilt binary distribution (cargo-dist + GitHub Releases) remains a possible future option, not part of the release flow.</li></ul>`,13)])])}const g=a(l,[["render",r]]);export{u as __pageData,g as default};
